INSERT INTO `Reizen` (`Reis_id`, `Bestemming`, `Land`, `korte_beschrijving`, `Prijs`, `Vlag`, `Continent`, `Strand_en_zon`, `Stedentrip`, `Wintersport`, `Natuur`, `Cultuur`, `Welkom_bericht`, `Historie`, `Wat_te_doen`, `kaart_afbeelding`) VALUES
(1, 'Willemstad', 'Curaçao', 'Willemstad is de hoofdstad van Curaçao en voormalige hoofdstad van de Nederlandse Antillen. Willemstad telt ~168.000 inwoners en is bekend voor zijn Amsterdam achtige gebouwen. De stad wordt ook wel de Amsterdam van de Nederlandse Antillen genoemd.', 950, 'Curacao.png', 'Noord-Amerika', 1, 0, 0, 0, 0, 'Welkom in Willemstad, het bruisende hart van Curaçao. Zodra je aankomt, word je omringd door kleurrijke gebouwen, een aangenaam klimaat en een ontspannen Caribische sfeer. De stad combineert Nederlandse architectuur met tropische invloeden, wat zorgt voor een unieke uitstraling die je nergens anders vindt. Wandel langs de beroemde waterkant, ontdek gezellige straatjes en geniet van de lokale cultuur. Of je nu komt voor een ontspannen vakantie, mooie foto\'s of het ontdekken van een nieuwe cultuur, Willemstad heeft voor iedere reiziger iets bijzonders te bieden. Wij zorgen ervoor dat jouw reis naar deze prachtige bestemming soepel begint met een comfortabele vlucht naar Curaçao.', 'De geschiedenis van Willemstad begon in 1634, toen de Nederlanders zich op Curaçao vestigden en een handelsnederzetting opbouwden rond een natuurlijke haven. Door de gunstige ligging groeide de stad uit tot een belangrijk handelscentrum in het Caribisch gebied. In de eeuwen daarna ontstonden verschillende wijken, zoals Punda en Otrobanda, die nog steeds het historische karakter van de stad bepalen. De Nederlandse invloeden zijn vandaag de dag duidelijk zichtbaar in de architectuur. Dankzij de goed bewaarde binnenstad en haven werd Willemstad in 1997 opgenomen op de Werelderfgoedlijst van UNESCO.', 'Willemstad biedt genoeg mogelijkheden voor een afwisselende vakantie. Bezoekers kunnen wandelen door de historische wijken Punda en Otrobanda, waar kleurrijke gebouwen en gezellige pleinen het straatbeeld bepalen. Ook de beroemde Koningin Emmabrug is een populaire bezienswaardigheid. Daarnaast zijn er diverse musea, winkels, restaurants en markten te vinden in de stad. Vanuit Willemstad zijn ook verschillende stranden gemakkelijk bereikbaar, waardoor een dag cultuur perfect gecombineerd kan worden met ontspanning aan zee. Of je nu houdt van geschiedenis, architectuur, winkelen of gewoon genieten van de Caribische sfeer, Willemstad heeft voor iedereen iets te bieden.', 'willemstad-card.png'),
(2, 'Ibiza', 'Spanje', 'Ibiza is een Spaans eiland in de Middellandse Zee en maakt deel uit van de Balearen. Het eiland staat wereldwijd bekend om zijn prachtige stranden, helderblauwe water en bruisende nachtleven. Jaarlijks trekken miljoenen bezoekers naar Ibiza om te genieten van de zon, de zee en de beroemde clubs. Dankzij de combinatie van ontspanning overdag en entertainment in de avond is Ibiza een van de populairste vakantiebestemmingen van Europa.', 240, 'Spanje.png', 'Europa', 1, 0, 0, 0, 0, 'Welkom op Ibiza, een eiland waar ontspanning en entertainment perfect samenkomen. Overdag kun je genieten van prachtige stranden, een warme zon en helder water, terwijl het eiland \'s avonds verandert in een van de bekendste uitgaansbestemmingen ter wereld. Of je nu wilt ontspannen aan zee, genieten van een strandwandeling of het bruisende nachtleven wilt ontdekken, Ibiza heeft voor iedere bezoeker iets te bieden. Dankzij het aangename klimaat en de unieke sfeer is het eiland een ideale bestemming voor een onvergetelijke vakantie.', 'Ibiza kent een lange geschiedenis die meer dan 2.500 jaar teruggaat. Het eiland werd oorspronkelijk gesticht door de Feniciërs en groeide later uit tot een belangrijk handelscentrum in de Middellandse Zee. Door de eeuwen heen stond Ibiza onder invloed van verschillende beschavingen, waaronder de Romeinen en de Moren. Deze invloeden zijn nog steeds terug te zien in de cultuur en architectuur van het eiland. Vanaf de tweede helft van de twintigste eeuw werd Ibiza steeds populairder als vakantiebestemming en ontwikkelde het zich tot een internationaal bekende toeristische trekpleister.', 'Ibiza staat vooral bekend om zijn stranden en uitgaansleven. Overdag kun je ontspannen op een van de vele zandstranden, zwemmen in het heldere water of genieten van verschillende watersporten. Langs de kust zijn gezellige strandtenten en restaurants te vinden waar je kunt genieten van de mediterrane sfeer. Wanneer de zon ondergaat, komt het beroemde nachtleven tot leven. Het eiland beschikt over enkele van de bekendste clubs ter wereld en trekt jaarlijks bezoekers die willen genieten van muziek, feesten en entertainment. Hierdoor biedt Ibiza een perfecte combinatie van ontspanning en avontuur.', 'ibiza-card.png'),
(3, 'Lissabon', 'Portugal', 'Lissabon is de hoofdstad van Portugal en ligt aan de westkust van het Iberisch Schiereiland. De stad staat bekend om haar kleurrijke gebouwen, historische wijken en ligging aan de Atlantische Oceaan. Met een rijke geschiedenis, een aangenaam klimaat en prachtige stranden in de omgeving trekt Lissabon jaarlijks miljoenen bezoekers. De combinatie van cultuur, moderne voorzieningen en ontspanning aan zee maakt de stad een van de populairste bestemmingen van Zuid-Europa.', 345, 'Portugal.png', 'Europa', 1, 1, 0, 0, 0, 'Welkom in Lissabon, een stad waar cultuur, geschiedenis en strand perfect samenkomen. Wandel door de sfeervolle straatjes van de historische binnenstad, geniet van het uitzicht vanaf een van de vele uitkijkpunten of ontdek de gezellige pleinen en cafés. Daarnaast liggen er verschillende prachtige stranden op korte afstand van het stadscentrum, waardoor je een stedentrip eenvoudig kunt combineren met een ontspannen dag aan zee. Dankzij het zonnige klimaat, de vriendelijke sfeer en de vele bezienswaardigheden is Lissabon een bestemming die voor iedere reiziger iets te bieden heeft.', 'Lissabon is een van de oudste steden van Europa en heeft een geschiedenis die meer dan tweeduizend jaar teruggaat. Door haar ligging aan de Atlantische Oceaan speelde de stad een belangrijke rol tijdens het Portugese tijdperk van ontdekkingsreizen in de vijftiende en zestiende eeuw. Vanuit Lissabon vertrokken beroemde ontdekkingsreizigers naar onbekende delen van de wereld. Hoewel een zware aardbeving in 1755 een groot deel van de stad verwoestte, werd Lissabon herbouwd en groeide het uit tot het politieke en economische centrum van Portugal. Tegenwoordig zijn veel historische gebouwen nog steeds te bewonderen.', 'Lissabon biedt een perfecte combinatie van stad en strand. Je kunt de historische wijken Alfama en Belém verkennen, een rit maken met de beroemde gele tram of genieten van het uitzicht vanaf een van de vele heuvels. Daarnaast zijn populaire stranden zoals Carcavelos en Costa da Caparica gemakkelijk bereikbaar vanuit de stad. Hier kun je zwemmen, zonnen of verschillende watersporten beoefenen. Ook zijn er talloze restaurants, winkels en culturele bezienswaardigheden te vinden. Dankzij deze combinatie van stedelijke activiteiten en strandplezier is Lissabon een veelzijdige vakantiebestemming.', 'lissabon-card.png'),
(4, 'Tokyo', 'Japan', 'Tokyo is de hoofdstad van Japan en een van de grootste en meest geavanceerde steden ter wereld. De stad staat bekend om haar indrukwekkende skyline, moderne technologie en unieke mix van traditie en innovatie. Van futuristische wijken tot rustige tempels, Tokyo biedt een enorme variatie aan ervaringen. Met miljoenen inwoners en eindeloze mogelijkheden op het gebied van eten, winkelen en cultuur is Tokyo een van de meest veelzijdige steden ter wereld.', 1100, 'Japan.png', 'Azië', 0, 1, 0, 0, 0, 'Welkom in Tokyo, een stad waar het moderne en het traditionele op een bijzondere manier samenkomen. Tijdens een bezoek ontdek je hypermoderne wijken vol neonlichten, maar ook rustige tempels en traditionele straatjes. Tokyo is een stad die nooit stil lijkt te staan en biedt een unieke energie die je nergens anders vindt. Of je nu wilt genieten van het uitzicht vanaf hoge wolkenkrabbers, lokale gerechten wilt proberen of door bijzondere buurten wilt wandelen, Tokyo heeft voor iedere bezoeker iets te bieden. Het is een bestemming die constant blijft verrassen.', 'Tokyo begon oorspronkelijk als een klein vissersdorp genaamd Edo. In de zeventiende eeuw groeide het uit tot het politieke centrum van Japan onder het shogunaat. In 1868 werd de stad hernoemd tot Tokyo en werd het de hoofdstad van Japan. Door de jaren heen groeide Tokyo uit tot een van de grootste en belangrijkste steden ter wereld. Ondanks zware verwoestingen tijdens de Tweede Wereldoorlog werd de stad snel herbouwd en gemoderniseerd. Tegenwoordig is Tokyo een wereldwijd centrum voor technologie, cultuur en economie.', 'Tokyo biedt een eindeloze hoeveelheid activiteiten voor bezoekers. Je kunt de moderne skyline bewonderen vanaf de Tokyo Skytree, de drukte ervaren op Shibuya Crossing of de luxe winkels in Ginza verkennen. Daarnaast zijn er rustige tempels zoals Senso-ji in Asakusa waar je de traditionele kant van Japan kunt ontdekken. Ook staan de vele wijken zoals Shinjuku en Harajuku bekend om hun unieke sfeer en entertainment. Dankzij de enorme diversiteit is Tokyo een stad waar je elke dag iets nieuws kunt ontdekken.', 'tokyo-card.png'),
(5, 'Miami', 'VS', 'Miami is een bruisende stad in de Amerikaanse staat Florida en staat wereldwijd bekend om haar prachtige stranden, moderne skyline en tropische klimaat. De stad trekt jaarlijks miljoenen bezoekers die komen genieten van de zon, de zee en het levendige uitgaansleven. Miami heeft daarnaast een mix van verschillende culturen, wat terug te zien is in de architectuur, muziek en keuken. Hierdoor is de stad een van de populairste vakantiebestemmingen van de Verenigde Staten.', 1050, 'VS.png', 'Noord-Amerika', 1, 1, 0, 0, 0, 'Welkom in Miami, een stad waar zon, strand en cultuur samenkomen. Met haar tropische klimaat, uitgestrekte zandstranden en levendige sfeer is Miami de perfecte bestemming voor een ontspannen vakantie. Overdag kun je genieten van het strand of de stad verkennen, terwijl je \'s avonds terecht kunt in gezellige restaurants en populaire uitgaansgelegenheden. De combinatie van moderne gebouwen, palmbomen en een multiculturele bevolking geeft Miami een unieke uitstraling. Of je nu wilt ontspannen aan zee of de stad wilt ontdekken, Miami biedt voor iedere reiziger een onvergetelijke ervaring.', 'Miami werd officieel gesticht in 1896 en groeide in korte tijd uit van een kleine nederzetting tot een belangrijke stad in Florida. Door de aanleg van spoorwegen werd de stad beter bereikbaar, wat zorgde voor een sterke groei van het toerisme. In de twintigste eeuw vestigden zich veel immigranten uit Latijns-Amerika, vooral uit Cuba, waardoor Miami een unieke culturele identiteit ontwikkelde. Tegenwoordig is de stad niet alleen een populaire vakantiebestemming, maar ook een belangrijk economisch en cultureel centrum van de Verenigde Staten.', 'Miami biedt volop mogelijkheden voor een veelzijdige vakantie. De beroemde stranden van Miami Beach zijn ideaal om te zwemmen, zonnen of watersporten te beoefenen. Daarnaast kun je wandelen langs Ocean Drive, bekend om zijn kleurrijke Art Deco-gebouwen en gezellige sfeer. Ook zijn er verschillende winkelgebieden, parken en musea te bezoeken. Voor liefhebbers van cultuur is de wijk Little Havana een aanrader, waar je de Cubaanse invloeden van de stad kunt ervaren. Of je nu kiest voor ontspanning aan het strand of het verkennen van de stad, in Miami is altijd iets te beleven.', 'miami-card.png'),
(9, 'Rio de Janeiro', 'Brazilië', 'Rio de Janeiro is een van de bekendste steden van Brazilië en ligt aan de Atlantische Oceaan. De stad staat wereldwijd bekend om haar prachtige stranden, warme klimaat en indrukwekkende kustlijn. Jaarlijks trekken miljoenen bezoekers naar Rio om te genieten van het strand, de zee en de ontspannen sfeer. Met beroemde stranden zoals Copacabana en Ipanema is Rio de Janeiro een van de populairste strandbestemmingen van Zuid-Amerika.', 1050, 'Brazilië.png', 'Zuid-Amerika', 1, 0, 0, 0, 0, 'Welkom in Rio de Janeiro, een stad waar het leven zich grotendeels afspeelt aan het strand. Met een aangenaam klimaat, gouden zandstranden en een levendige sfeer is Rio de perfecte bestemming voor liefhebbers van zon en zee. Overdag kun je ontspannen op de beroemde stranden van Copacabana en Ipanema, terwijl je geniet van het uitzicht op de oceaan. De combinatie van tropische temperaturen, helder water en een ontspannen levensstijl maakt Rio de Janeiro tot een ideale vakantiebestemming. Of je nu wilt zwemmen, zonnen of gewoon wilt genieten van de unieke sfeer, Rio heeft alles voor een onvergetelijke strandvakantie.', 'Rio de Janeiro werd in 1565 gesticht door de Portugezen en groeide uit tot een van de belangrijkste steden van Brazilië. De stad was lange tijd de hoofdstad van het land en speelde een belangrijke rol in de handel en ontwikkeling van Brazilië. Door de ligging aan de kust werd Rio een belangrijk haven- en handelscentrum. In de twintigste eeuw groeide het toerisme sterk, mede dankzij de beroemde stranden en het aangename klimaat. Tegenwoordig behoort Rio de Janeiro tot de meest bezochte steden van Zuid-Amerika en is het wereldwijd bekend als een populaire vakantiebestemming.', 'De stranden vormen zonder twijfel de grootste trekpleister van Rio de Janeiro. Copacabana en Ipanema behoren tot de bekendste stranden ter wereld en zijn perfect om te zwemmen, zonnen of een wandeling langs de boulevard te maken. Ook zijn er mogelijkheden voor activiteiten zoals beachvolleybal, surfen en andere watersporten. Langs de stranden vind je talloze cafés, restaurants en plekken om te ontspannen. Dankzij het warme weer gedurende een groot deel van het jaar is Rio de Janeiro een ideale bestemming voor iedereen die wil genieten van een vakantie aan zee.', 'rio-card.png'),
(10, 'Cairo', 'Egypte', 'Caïro is de hoofdstad van Egypte en de grootste stad van Afrika. De stad ligt aan de rivier de Nijl en staat wereldwijd bekend om haar nabijheid tot de beroemde piramides van Gizeh en de Sfinx. Caïro combineert een eeuwenoude geschiedenis met een levendige moderne metropool. Bezoekers komen hier vooral voor de indrukwekkende oude beschavingen, monumentale gebouwen en archeologische schatten die de stad en omgeving uniek maken.', 625, 'Egypte.png', 'Afrika', 0, 0, 0, 0, 1, 'Welkom in Caïro, een stad waar je geschiedenis op een ongekende schaal ervaart. In en rondom de stad vind je enkele van de meest iconische bouwwerken ter wereld, waaronder de piramides van Gizeh en de Sfinx. Deze eeuwenoude monumenten maken Caïro tot een van de belangrijkste historische bestemmingen ter wereld. Tegelijkertijd is de stad zelf levendig en druk, met markten, pleinen en een mix van oude en moderne wijken. Voor reizigers die geïnteresseerd zijn in de oude wereld en indrukwekkende architectuur is Caïro een bestemming die je niet snel vergeet.', 'Caïro werd in de tiende eeuw gesticht door de Fatimiden, maar de regio rond de stad heeft een veel oudere geschiedenis. In de nabijgelegen oud-Egyptische beschaving werden al duizenden jaren geleden de beroemde piramides gebouwd als grafmonumenten voor farao’s. Deze bouwwerken behoren tot de zeven wereldwonderen van de antieke wereld en zijn tot op de dag van vandaag bewaard gebleven. Door de eeuwen heen groeide Caïro uit tot een belangrijk cultureel en religieus centrum in de Arabische wereld. Tegenwoordig is de stad een levendige metropool waar het verleden en het heden samenkomen.', 'Caïro biedt een indrukwekkende hoeveelheid historische bezienswaardigheden. De piramides van Gizeh en de Sfinx zijn zonder twijfel de grootste trekpleister en liggen net buiten de stad. Daarnaast kun je het Egyptisch Museum bezoeken, waar duizenden oude artefacten te zien zijn, waaronder schatten uit het graf van Toetanchamon. Ook de oude islamitische wijk van Caïro, met haar moskeeën en markten, is een bezoek waard. Een wandeling door de stad laat de mix van oud en modern goed zien. Voor liefhebbers van geschiedenis is Caïro een van de meest indrukwekkende bestemmingen ter wereld.', 'cairo-card.png'),
(11, 'Milaan', 'Italië', 'Milaan is een grote stad in het noorden van Italië en staat bekend als een van de belangrijkste mode- en designhoofdsteden van de wereld. Naast haar moderne en stijlvolle uitstraling heeft de stad ook een rijke geschiedenis en indrukwekkende architectuur. Bezienswaardigheden zoals de Duomo di Milano en het Castello Sforzesco trekken jaarlijks veel bezoekers. Milaan combineert cultuur, historie en een levendig stadsleven, waardoor het een populaire bestemming is voor stedentrips.', 200, 'Italië.png', 'Europa', 0, 1, 0, 0, 1, 'Welkom in Milaan, een stad waar geschiedenis en modern leven samenkomen. Tijdens een bezoek ontdek je indrukwekkende gebouwen, elegante winkelstraten en een rijke culturele sfeer. De stad staat bekend om haar stijlvolle uitstraling, maar heeft ook een diep historisch verleden dat nog steeds zichtbaar is in het centrum. Van grote pleinen tot eeuwenoude kerken en kastelen: Milaan heeft voor iedere bezoeker iets te bieden. Of je nu geïnteresseerd bent in architectuur, cultuur of gewoon wilt genieten van een levendige Italiaanse stad, Milaan is een bestemming die je blijft verrassen.', 'Milaan werd oorspronkelijk gesticht door de Kelten en later veroverd door de Romeinen, die de stad Mediolanum noemden. In de Middeleeuwen groeide Milaan uit tot een belangrijk handels- en machtscentrum in Noord-Italië. Onder invloed van invloedrijke families zoals de Visconti en Sforza werd de stad verder ontwikkeld en verrijkt met indrukwekkende bouwwerken. Tijdens de Renaissance speelde Milaan een belangrijke rol in kunst en architectuur. Tegenwoordig is de stad uitgegroeid tot een wereldwijd centrum voor mode, design en economie, terwijl het historische erfgoed nog steeds duidelijk zichtbaar is.', 'Milaan biedt een mix van historische en moderne bezienswaardigheden. Het bekendste monument is de Duomo di Milano, een indrukwekkende kathedraal midden in de stad. Daarnaast kun je het Castello Sforzesco bezoeken of wandelen door de stijlvolle winkelgalerij Galleria Vittorio Emanuele II. Voor liefhebbers van kunst en geschiedenis zijn er verschillende musea en kerken met eeuwenoude werken. Ook de wijk Brera is populair vanwege de gezellige sfeer en culturele uitstraling. Dankzij de combinatie van historie, architectuur en modern stadsleven is Milaan een veelzijdige bestemming voor een stedentrip.', 'milaan-card.png'),
(12, 'Tromsø', 'Noorwegen', 'Tromsø is een stad in het noorden van Noorwegen, gelegen boven de poolcirkel. De stad staat bekend als een van de beste plekken ter wereld om het noorderlicht te zien en is daarnaast een populaire wintersportbestemming. Met besneeuwde landschappen, fjorden en een echt Arctisch klimaat trekt Tromsø jaarlijks veel avontuurlijke reizigers. Naast wintersport biedt de stad ook unieke natuurervaringen en een bijzondere winterse sfeer.', 350, 'Noorwegen.png', 'Europa', 0, 0, 1, 1, 0, 'Welkom in Tromsø, een echte winterbestemming in het hoge noorden van Noorwegen. Hier draait alles om sneeuw, natuur en unieke ervaringen die je nergens anders vindt. Tijdens de wintermaanden verandert het landschap in een witte wereld waar je kunt skiën, sneeuwschoenwandelen of simpelweg genieten van de stilte van de natuur. Daarnaast is Tromsø wereldwijd beroemd als een van de beste plekken om het noorderlicht te bewonderen. De combinatie van ruige natuur, frisse lucht en bijzondere winteractiviteiten maakt deze bestemming perfect voor liefhebbers van wintersport en avontuur.', 'Tromsø heeft een lange geschiedenis als belangrijk handels- en visserscentrum in Noord-Noorwegen. Door de ligging boven de poolcirkel werd de stad al vroeg een uitvalsbasis voor Arctische expedities. In de negentiende en twintigste eeuw speelde Tromsø een belangrijke rol in poolexploraties en wetenschappelijk onderzoek in het noorden. Ondanks het barre klimaat groeide de stad uit tot een levendige gemeenschap. Tegenwoordig combineert Tromsø haar historische rol in de poolgebieden met moderne voorzieningen en toerisme, vooral gericht op winteractiviteiten en natuurbeleving.', 'Tromsø is een paradijs voor wintersport- en natuurliefhebbers. Je kunt er skiën, sneeuwschoenwandelen en hondensledetochten maken door het besneeuwde landschap. Ook zijn er georganiseerde excursies om het noorderlicht te bewonderen, een van de grootste trekpleisters van de regio. Daarnaast kun je genieten van het uitzicht op fjorden en bergen rondom de stad. In het centrum van Tromsø vind je musea, restaurants en gezellige cafés waar je kunt opwarmen na een dag in de kou. Dankzij de combinatie van avontuur en natuur is Tromsø een unieke winterbestemming.', 'tromso-card.png'),
(16, 'Banff', 'Canada', 'Banff is een populaire bergplaats in de Canadese provincie Alberta, gelegen in de indrukwekkende Rocky Mountains. Het dorp staat bekend om zijn prachtige natuur, besneeuwde bergtoppen en uitstekende wintersportmogelijkheden. Jaarlijks trekken duizenden toeristen naar Banff om te skiën, snowboarden en te genieten van het winterse landschap. Dankzij de combinatie van moderne voorzieningen en ongerepte natuur is Banff een van de bekendste wintersportbestemmingen van Noord-Amerika.', 1000, 'Canada.png', 'Noord-Amerika', 0, 0, 1, 1, 0, 'Welkom in Banff, een van de mooiste wintersportbestemmingen ter wereld. Midden in de Canadese Rocky Mountains vind je een unieke combinatie van spectaculaire natuur, gezellige sfeer en uitstekende skigebieden. Of je nu een ervaren skiër bent of voor het eerst op de piste staat, Banff biedt voor iedereen een onvergetelijke ervaring. Naast wintersport kun je genieten van besneeuwde bossen, indrukwekkende berglandschappen en het gezellige centrum met winkels en restaurants. Met een reis naar Banff beleef je een wintervakantie die je niet snel zult vergeten.', 'De geschiedenis van Banff begon aan het einde van de 19e eeuw, toen arbeiders tijdens de aanleg van de Canadian Pacific Railway natuurlijke warmwaterbronnen ontdekten. Om dit bijzondere gebied te beschermen werd in 1885 Banff National Park opgericht, het eerste nationale park van Canada. Door de aanleg van spoorwegen en later wegen groeide Banff uit tot een populaire bestemming voor natuurliefhebbers en toeristen. In de twintigste eeuw ontwikkelde het gebied zich verder tot een internationaal bekende wintersportlocatie. Tegenwoordig bezoeken miljoenen mensen jaarlijks Banff om te genieten van de natuur en de vele recreatiemogelijkheden.', 'Banff staat vooral bekend om de uitstekende wintersportmogelijkheden. In de omgeving liggen meerdere skigebieden met pistes voor zowel beginners als gevorderden. Naast skiën en snowboarden kun je ook wandelen door besneeuwde natuurgebieden, schaatsen op bevroren meren of genieten van een rit met een gondelbaan voor een prachtig uitzicht over de bergen. In het centrum van Banff zijn daarnaast verschillende winkels, restaurants en cafés te vinden. Voor wie van avontuur en natuur houdt, is Banff een ideale bestemming voor een actieve wintervakantie.', 'banff-alberta.jpg'),
(17, 'Los Angeles', 'VS', 'Los Angeles is een van de grootste steden van de Verenigde Staten en ligt aan de westkust van Californië. De stad staat bekend om haar zonnige klimaat, beroemde stranden en de filmindustrie van Hollywood. Jaarlijks bezoeken miljoenen toeristen Los Angeles om de bekende bezienswaardigheden te bekijken, te winkelen en te genieten van de ontspannen sfeer. Door de combinatie van cultuur, entertainment en natuur is Los Angeles een van de populairste bestemmingen van Noord-Amerika.', 1200, 'VS.png', 'Noord-Amerika', 1, 1, 0, 0, 0, 'Welkom in Los Angeles, de stad van zon, strand en entertainment. Hier kun je genieten van uitgestrekte stranden, beroemde bezienswaardigheden en een levendige sfeer die je nergens anders vindt. Of je nu wilt ontspannen aan de kust, door de stad wilt wandelen of iconische plekken zoals Hollywood wilt bezoeken, Los Angeles heeft voor iedere reiziger iets te bieden. De stad combineert een modern stadsleven met prachtige natuur en een ontspannen Californische levensstijl. Een bezoek aan Los Angeles staat garant voor een afwisselende en onvergetelijke vakantie.', 'Los Angeles werd in 1781 gesticht door Spaanse kolonisten en begon als een kleine nederzetting. In de negentiende eeuw werd de stad onderdeel van de Verenigde Staten en groeide zij snel dankzij de landbouw, handel en later de olie-industrie. In het begin van de twintigste eeuw vestigden veel filmstudio\'s zich in Hollywood, waardoor Los Angeles uitgroeide tot het wereldcentrum van de filmindustrie. Tegenwoordig is de stad een van de belangrijkste culturele, economische en toeristische centra van de Verenigde Staten en trekt zij bezoekers van over de hele wereld.', 'Los Angeles biedt een groot aantal activiteiten voor bezoekers. De stranden van Santa Monica en Venice Beach zijn populair om te zwemmen, fietsen of te genieten van de zon. Daarnaast kun je beroemde plekken bezoeken zoals Hollywood Boulevard, de Walk of Fame en het Griffith Observatory. Ook zijn er veel winkels, restaurants en musea verspreid door de stad. Voor liefhebbers van entertainment zijn er diverse filmstudio\'s en attractieparken te bezoeken. Dankzij de combinatie van stranden, cultuur en bezienswaardigheden is er in Los Angeles altijd iets te beleven.', 'los-angeles.png'),
(18, 'Honolulu', 'VS', 'Honolulu is de hoofdstad van de Amerikaanse staat Hawaï en ligt op het eiland Oahu. De stad staat bekend om haar prachtige stranden, tropische klimaat en ontspannen sfeer. Jaarlijks trekken miljoenen bezoekers naar Honolulu om te genieten van de zon en de zee. Met zijn palmbomen, helderblauwe water en aangename temperaturen het hele jaar door is Honolulu een van de populairste strandbestemmingen ter wereld.', 1400, 'VS.png', 'Noord-Amerika', 1, 0, 0, 0, 0, 'Welkom in Honolulu, een tropisch paradijs waar zon, strand en ontspanning centraal staan. Deze prachtige bestemming op het eiland Oahu biedt het hele jaar door warm weer en een ontspannen sfeer. Of je nu wilt genieten van de beroemde stranden, zwemmen in de heldere oceaan of simpelweg wilt ontspannen onder de palmbomen, Honolulu heeft alles voor een heerlijke vakantie. De combinatie van prachtige natuur, gastvrije cultuur en een aangenaam klimaat maakt deze stad tot een ideale bestemming voor reizigers die willen ontsnappen aan het dagelijkse leven en volledig tot rust willen komen.', 'Honolulu heeft een rijke geschiedenis die teruggaat tot de oorspronkelijke Polynesische bewoners van Hawaï. In de negentiende eeuw groeide de stad uit tot een belangrijk handelscentrum in de Stille Oceaan. Later werd Honolulu de hoofdstad van het Koninkrijk Hawaï en uiteindelijk van de Amerikaanse staat Hawaï. De stad speelde ook een belangrijke rol tijdens de Tweede Wereldoorlog vanwege de nabijgelegen marinebasis Pearl Harbor. Tegenwoordig is Honolulu een moderne stad die haar historische en culturele achtergrond heeft weten te combineren met een bloeiende toeristische sector.', 'Honolulu staat vooral bekend om zijn prachtige stranden en aangename weer. Het beroemde Waikiki Beach is de ideale plek om te zwemmen, zonnen of te leren surfen. Daarnaast kun je genieten van wandelingen langs de kust, prachtige zonsondergangen en indrukwekkende uitzichten over de oceaan. Voor natuurliefhebbers zijn er verschillende wandelroutes in de omgeving, waaronder de bekende Diamond Head-krater. Ook biedt de stad diverse winkels, restaurants en lokale markten. Of je nu actief bezig wilt zijn of juist wilt ontspannen, Honolulu biedt alles voor een perfecte strandvakantie.', 'Honolulu.png'),
(19, 'New York', 'VS', 'New York City is de grootste stad van de Verenigde Staten en staat bekend als een van de meest invloedrijke steden ter wereld. De stad bestaat uit vijf stadsdelen en trekt jaarlijks miljoenen bezoekers. New York wordt vaak de \"Concrete Jungle\" genoemd vanwege de indrukwekkende wolkenkrabbers en het drukke stadsleven. Bekende bezienswaardigheden zijn Times Square, Central Park, de Empire State Building en het Vrijheidsbeeld (Statue of Liberty), dat symbool staat voor vrijheid en hoop.', 800, 'VS.png', 'Noord-Amerika', 0, 1, 0, 0, 0, 'Welkom in New York City, de stad die nooit slaapt. Hier vind je een unieke combinatie van indrukwekkende wolkenkrabbers, wereldberoemde bezienswaardigheden en een sfeer die nergens anders te vinden is. Wandel door de drukke straten van Manhattan, bewonder de skyline vanaf verschillende uitkijkpunten of bezoek iconische locaties zoals Times Square en het Vrijheidsbeeld. New York biedt voor iedere bezoeker iets bijzonders, van cultuur en geschiedenis tot winkelen en entertainment. Of het nu je eerste bezoek is of je tiende, deze wereldstad blijft verrassen en inspireren.', 'New York City werd oorspronkelijk gesticht door Nederlandse kolonisten in de zeventiende eeuw onder de naam Nieuw-Amsterdam. Nadat de Engelsen de stad overnamen, kreeg zij haar huidige naam. Door haar gunstige ligging groeide New York uit tot een belangrijk handels- en immigratiecentrum. Miljoenen mensen kwamen via Ellis Island de Verenigde Staten binnen op zoek naar een nieuw leven. Een belangrijke gebeurtenis in de moderne geschiedenis was de aanslag van 11 september 2001, waarbij de Twin Towers van het World Trade Center werden verwoest. Tegenwoordig herinnert het 9/11 Memorial aan deze gebeurtenis. New York is uitgegroeid tot een van de belangrijkste steden op het gebied van economie, cultuur en politiek.', 'In New York City is er altijd iets te beleven. Bezoek het beroemde Vrijheidsbeeld, wandel door Central Park of geniet van het uitzicht vanaf de Empire State Building of One World Observatory. Ook Times Square, Broadway en de Brooklyn Bridge behoren tot de populairste attracties van de stad. Daarnaast kun je uitgebreid winkelen op Fifth Avenue, verschillende musea bezoeken of genieten van de vele restaurants en cafés. Dankzij de enorme hoeveelheid bezienswaardigheden en activiteiten is New York een bestemming waar je je geen moment hoeft te vervelen.', 'new-york.jpg'),
(20, 'Mexico City', 'Mexico', 'Mexico City is de hoofdstad van Mexico en een van de grootste steden ter wereld. De stad telt miljoenen inwoners en staat bekend om haar rijke cultuur, indrukwekkende geschiedenis en levendige sfeer. Bezoekers kunnen genieten van historische gebouwen, moderne wijken, grote parken en talloze musea. Door de combinatie van oude tradities en een moderne uitstraling is Mexico City een populaire bestemming voor reizigers die een unieke stedentrip willen beleven.', 1200, 'Mexico.png', 'Noord-Amerika', 0, 1, 0, 0, 0, 'Welkom in Mexico City, een bruisende metropool vol cultuur, geschiedenis en leven. Deze indrukwekkende hoofdstad biedt een unieke mix van historische bezienswaardigheden, moderne architectuur en gezellige pleinen. Tijdens een bezoek kun je genieten van de Mexicaanse keuken, kleurrijke markten en wereldberoemde musea. De stad heeft voor iedere bezoeker iets te bieden, of je nu geïnteresseerd bent in geschiedenis, kunst of het ontdekken van het dagelijkse leven in Mexico. Dankzij de levendige sfeer en de vele bezienswaardigheden is Mexico City een bestemming die je niet snel zult vergeten.', 'De geschiedenis van Mexico City gaat terug tot de Azteken, die in de veertiende eeuw de stad Tenochtitlan bouwden op een eiland in het Texcocomeer. Nadat de Spaanse veroveraars arriveerden in de zestiende eeuw, werd de stad grotendeels herbouwd en groeide zij uit tot het politieke en economische centrum van Nieuw-Spanje. Na de onafhankelijkheid van Mexico bleef Mexico City zich ontwikkelen tot de hoofdstad van het land. Tegenwoordig zijn nog steeds veel sporen van zowel de Azteekse als de Spaanse geschiedenis zichtbaar, wat de stad tot een van de meest historisch interessante bestemmingen van Latijns-Amerika maakt.', 'Mexico City biedt een groot aantal activiteiten voor bezoekers. Je kunt het historische centrum verkennen, het indrukwekkende Zócalo-plein bezoeken of een kijkje nemen bij de oude Azteekse ruïnes van Templo Mayor. Daarnaast zijn er bekende musea, grote stadsparken en gezellige markten waar je de lokale cultuur kunt ervaren. Ook de vele restaurants maken de stad populair bij liefhebbers van eten.', 'mexico-city.jpg'),
(21, 'Cancun', 'Mexico', 'Cancún is een populaire badplaats aan de oostkust van Mexico, gelegen aan de Caribische Zee. De stad staat bekend om haar witte zandstranden, helderblauwe water en tropische klimaat. Jaarlijks bezoeken miljoenen toeristen Cancún om te genieten van de zon en de prachtige kustlijn. Daarnaast is de regio rijk aan geschiedenis, met verschillende Maya-tempels en archeologische vindplaatsen in de omgeving. Hierdoor is Cancún een ideale bestemming voor zowel strandliefhebbers als cultuurliefhebbers.', 1300, 'Mexico.png', 'Noord-Amerika', 1, 0, 0, 0, 1, 'Welkom in Cancún, een tropische bestemming waar ontspanning en cultuur samenkomen. Hier kun je genieten van kilometerslange stranden, een warme zon en het prachtige water van de Caribische Zee. Naast de bekende resorts en stranden biedt de regio ook een fascinerende geschiedenis die teruggaat tot de tijd van de Maya\'s. Of je nu wilt ontspannen aan het strand, zwemmen in de zee of historische locaties wilt ontdekken, Cancún heeft voor iedere reiziger iets te bieden. Dankzij het heerlijke klimaat en de veelzijdige activiteiten is het een perfecte bestemming voor een onvergetelijke vakantie.', 'Hoewel Cancún zelf een relatief jonge stad is die pas in de jaren zeventig sterk werd ontwikkeld voor toerisme, heeft de regio een veel langere geschiedenis. Het gebied maakte deel uit van de beschaving van de Maya\'s, die eeuwenlang grote steden en tempels bouwden op het schiereiland Yucatán. In de omgeving van Cancún zijn nog altijd indrukwekkende archeologische vindplaatsen te vinden die herinneren aan deze bijzondere cultuur. Tegenwoordig combineert de stad haar moderne toeristische voorzieningen met de rijke geschiedenis van de regio, waardoor bezoekers zowel ontspanning als cultuur kunnen ervaren.', 'Cancún biedt volop mogelijkheden voor een afwisselende vakantie. De prachtige stranden zijn ideaal om te zwemmen, snorkelen of gewoon te genieten van de zon. Daarnaast kun je een bezoek brengen aan beroemde Maya-tempels zoals Chichén Itzá, een van de bekendste archeologische locaties van Mexico. Ook zijn er verschillende natuurgebieden, cenotes en eilanden in de omgeving die zeker een bezoek waard zijn. Voor liefhebbers van cultuur, geschiedenis en natuur biedt Cancún veel meer dan alleen strand. Hierdoor is het een bestemming die zowel ontspanning als avontuur combineert.', 'cancun.jpg'),
(22, 'Montevideo', 'Uruguay', 'Montevideo is de hoofdstad van Uruguay en ligt aan de kust van de Río de la Plata. De stad staat bekend om haar ontspannen sfeer, brede stranden en rijke cultuur. Met ruim 1,3 miljoen inwoners is Montevideo het politieke, economische en culturele centrum van het land. Bezoekers waarderen de combinatie van historische gebouwen, moderne voorzieningen en de lange boulevard langs de kust, waardoor de stad een populaire bestemming is voor zowel stedentrips als strandvakanties.', 1300, 'Uruguay.png', 'Zuid-Amerika', 1, 1, 0, 0, 0, 'Welkom in Montevideo, een stad waar cultuur, geschiedenis en ontspanning perfect samenkomen. Deze sfeervolle hoofdstad biedt een mix van historische gebouwen, gezellige pleinen en prachtige stranden langs de kust. Overdag kun je de stad verkennen, genieten van lokale restaurants of wandelen langs de beroemde Rambla, de boulevard die zich kilometers langs de kust uitstrekt. Dankzij de ontspannen sfeer en vriendelijke bevolking voelt Montevideo direct gastvrij aan. Of je nu komt voor de stad, de stranden of een combinatie van beide, Montevideo heeft voor iedere bezoeker iets te bieden.', 'Montevideo werd in 1726 gesticht door de Spanjaarden als verdedigingspost aan de kust van Zuid-Amerika. Door de gunstige ligging groeide de stad uit tot een belangrijk handelscentrum en speelde zij een grote rol in de ontwikkeling van Uruguay. In de negentiende eeuw werd Montevideo het politieke hart van het land en bleef het zich verder ontwikkelen. Tegenwoordig zijn veel historische gebouwen en pleinen nog steeds goed bewaard gebleven. Deze rijke geschiedenis is overal in de stad terug te zien en vormt een belangrijk onderdeel van de identiteit van Montevideo.', 'Montevideo biedt volop mogelijkheden voor een afwisselende vakantie. Je kunt wandelen door de historische binnenstad, een bezoek brengen aan lokale markten of genieten van de vele restaurants en cafés. Daarnaast zijn de stranden van de stad populair bij zowel inwoners als toeristen. Langs de kust loopt de beroemde Rambla, een boulevard die ideaal is om te wandelen, fietsen of te genieten van het uitzicht over het water. Dankzij de combinatie van cultuur, geschiedenis, winkels en stranden is Montevideo een bestemming waar altijd iets te beleven valt.', 'montevideo.jpg'),
(23, 'Sao Paulo', 'Brazilië', 'São Paulo is de grootste stad van Brazilië en een van de grootste steden ter wereld. De stad telt meer dan 12 miljoen inwoners en staat bekend als het economische en culturele centrum van het land. São Paulo biedt een indrukwekkende skyline, talloze musea, winkelgebieden en een bruisend stadsleven. Door de mix van verschillende culturen, moderne architectuur en levendige sfeer is de stad een populaire bestemming voor reizigers die een echte wereldstad willen ervaren.', 1050, 'Brazilië.png', 'Zuid-Amerika', 0, 1, 0, 0, 0, 'Welkom in São Paulo, een stad die nooit stil lijkt te staan. Deze enorme metropool biedt een unieke combinatie van cultuur, entertainment, gastronomie en moderne architectuur. Tijdens een bezoek kun je genieten van wereldberoemde musea, grote winkelstraten, gezellige parken en een van de meest diverse keukens ter wereld. De stad staat bekend om haar energieke sfeer en biedt voor iedere bezoeker iets bijzonders. Of je nu geïnteresseerd bent in kunst, geschiedenis, winkelen of het ontdekken van een nieuwe cultuur, São Paulo is een bestemming die je blijft verrassen.', 'São Paulo werd in 1554 gesticht door Jezuïetenmissionarissen en begon als een kleine religieuze nederzetting. In de negentiende eeuw groeide de stad snel dankzij de bloeiende koffiehandel, die veel welvaart naar de regio bracht. Later zorgden industrialisatie en immigratie uit Europa, Azië en het Midden-Oosten voor een verdere groei van de stad. Hierdoor ontwikkelde São Paulo zich tot het economische hart van Brazilië. Tegenwoordig is de stad een belangrijk centrum voor handel, financiën, cultuur en technologie in Zuid-Amerika.', 'São Paulo biedt een enorme hoeveelheid activiteiten voor bezoekers. Je kunt het beroemde Avenida Paulista verkennen, een van de belangrijkste straten van de stad, of een bezoek brengen aan een van de vele musea en kunstgalerieën. Daarnaast zijn er grote parken zoals Ibirapuera Park waar je kunt ontspannen midden in de drukke stad. Voor liefhebbers van winkelen zijn er talloze winkelcentra en markten te vinden. Ook staat São Paulo bekend om haar uitstekende restaurants en diverse keuken. Dankzij de combinatie van cultuur, entertainment en moderne voorzieningen is er in deze wereldstad altijd iets te beleven.', 'sao-paulo.jpg'),
(24, 'Parijs', 'Frankrijk', 'Parijs is de hoofdstad van Frankrijk en een van de meest bezochte steden ter wereld. De stad staat bekend om haar rijke geschiedenis, indrukwekkende architectuur en unieke cultuur. Met beroemde bezienswaardigheden zoals de Eiffeltoren, het Louvre en de Notre-Dame trekt Parijs jaarlijks miljoenen bezoekers. Dankzij de combinatie van kunst, historie en een levendige sfeer wordt de stad vaak gezien als een van de mooiste en meest culturele bestemmingen van Europa.', 200, 'France.png', 'Europa', 0, 1, 0, 0, 1, 'Welkom in Parijs, de stad van licht, kunst en cultuur. In deze wereldberoemde hoofdstad vind je indrukwekkende monumenten, sfeervolle straten en een rijke geschiedenis die op elke hoek zichtbaar is. Wandel langs de Seine, bewonder de Eiffeltoren of ontdek de vele musea die Parijs te bieden heeft. De stad staat bekend om haar unieke sfeer en trekt bezoekers van over de hele wereld. Of je nu geïnteresseerd bent in kunst, geschiedenis, architectuur of gewoon wilt genieten van de Franse cultuur, Parijs biedt een ervaring die je niet snel zult vergeten.', 'De geschiedenis van Parijs gaat meer dan tweeduizend jaar terug. Oorspronkelijk ontstond de stad als een nederzetting van de Gallische stam van de Parisii, waarna zij onder de Romeinen verder groeide. In de eeuwen daarna ontwikkelde Parijs zich tot het politieke, economische en culturele centrum van Frankrijk. De stad speelde een belangrijke rol tijdens gebeurtenissen zoals de Franse Revolutie en groeide uit tot een van de invloedrijkste steden van Europa. Tegenwoordig zijn veel historische gebouwen en monumenten nog steeds goed bewaard gebleven, waardoor bezoekers overal sporen van het verleden kunnen ontdekken.', 'Parijs biedt een groot aantal activiteiten voor bezoekers. Je kunt de Eiffeltoren beklimmen, een bezoek brengen aan het wereldberoemde Louvre of wandelen door de historische straten van Montmartre. Daarnaast zijn er talloze musea, theaters en galerieën die de rijke cultuur van de stad laten zien. Ook een boottocht over de Seine is een populaire manier om Parijs te verkennen. Voor liefhebbers van winkelen zijn er bekende winkelstraten en luxe boetieks te vinden. Dankzij de combinatie van cultuur, geschiedenis en bezienswaardigheden is er in Parijs altijd iets te beleven.', 'parijs.png'),
(25, 'Rome', 'Italië', 'Rome is de hoofdstad van Italië en een van de meest historische steden ter wereld. De stad staat bekend om haar indrukwekkende monumenten, eeuwenoude gebouwen en rijke cultuur. Bezienswaardigheden zoals het Colosseum, het Forum Romanum en het Pantheon trekken jaarlijks miljoenen bezoekers. Dankzij de combinatie van geschiedenis, architectuur en het Italiaanse stadsleven is Rome een van de populairste bestemmingen van Europa.', 340, 'Italië.png', 'Europa', 0, 1, 0, 0, 1, 'Welkom in Rome, een stad waar geschiedenis op elke straathoek tot leven komt. Tijdens een bezoek wandel je langs eeuwenoude monumenten, indrukwekkende pleinen en beroemde gebouwen die een belangrijke rol hebben gespeeld in de wereldgeschiedenis. Tegelijkertijd biedt Rome een levendige sfeer met gezellige cafés, restaurants en winkelstraten. Of je nu geïnteresseerd bent in de Romeinse Oudheid, kunst of cultuur, de Italiaanse hoofdstad heeft voor iedere bezoeker iets bijzonders te bieden. Een reis naar Rome is een unieke kans om duizenden jaren geschiedenis van dichtbij te beleven.', 'Rome werd volgens de legende gesticht in 753 voor Christus en groeide uit tot het centrum van het machtige Romeinse Rijk. Vanuit deze stad werd een groot deel van Europa, Noord-Afrika en het Midden-Oosten bestuurd. Veel beroemde bouwwerken, zoals het Colosseum en het Forum Romanum, herinneren nog aan deze periode. Na de val van het Romeinse Rijk bleef Rome een belangrijk religieus en cultureel centrum, mede dankzij de aanwezigheid van het Vaticaan. Tegenwoordig wordt de stad beschouwd als een van de belangrijkste historische bestemmingen ter wereld, waar meer dan tweeduizend jaar geschiedenis zichtbaar is.', 'Rome biedt talloze mogelijkheden voor liefhebbers van geschiedenis en cultuur. Bezoek het beroemde Colosseum, wandel door het Forum Romanum of bewonder het Pantheon, een van de best bewaarde gebouwen uit de Romeinse tijd. Ook het Vaticaan, met de Sint-Pietersbasiliek en de Sixtijnse Kapel, behoort tot de hoogtepunten van de stad. Daarnaast kun je genieten van sfeervolle pleinen zoals Piazza Navona en de beroemde Trevifontein bezoeken. Dankzij de enorme hoeveelheid historische bezienswaardigheden voelt een wandeling door Rome als een reis door de geschiedenis.', 'rome.jpg'),
(26, 'Athene', 'Griekenland', 'Athene is de hoofdstad van Griekenland en een van de oudste steden ter wereld. De stad wordt gezien als de geboorteplaats van de westerse beschaving en staat bekend om haar enorme historische en culturele betekenis. Bezienswaardigheden zoals de Akropolis, het Parthenon en de oude agora trekken jaarlijks miljoenen bezoekers. Athene combineert een rijke oudheid met een levendige moderne stad, waardoor het een unieke bestemming is voor liefhebbers van geschiedenis.', 350, 'Greece.png', 'Europa', 0, 1, 0, 0, 1, 'Welkom in Athene, een stad waar je letterlijk door duizenden jaren geschiedenis wandelt. Overal in de stad vind je sporen van het oude Griekenland, van indrukwekkende tempels tot archeologische opgravingen midden in het centrum. De Akropolis torent hoog boven de stad uit en vormt het symbool van de klassieke oudheid. Naast de historische rijkdom biedt Athene ook een levendige sfeer met gezellige wijken, pleinen en cafés. Voor iedereen die geïnteresseerd is in geschiedenis, mythologie en de oorsprong van de westerse wereld is Athene een onvergetelijke bestemming.', 'Athene heeft een geschiedenis die meer dan 3.000 jaar teruggaat en wordt vaak beschouwd als de wieg van de democratie. In de klassieke oudheid was de stad een van de machtigste stadstaten van Griekenland en een belangrijk centrum voor filosofie, kunst en wetenschap. Denkers zoals Socrates, Plato en Aristoteles hebben hier hun ideeën ontwikkeld. In deze periode werden ook iconische bouwwerken zoals het Parthenon gebouwd op de Akropolis. Ondanks verschillende overheersingen in latere eeuwen bleef Athene een belangrijk cultureel centrum. Tegenwoordig is de stad wereldwijd bekend om haar uitzonderlijke historische erfgoed.', 'Athene biedt een enorme hoeveelheid historische bezienswaardigheden. De Akropolis is zonder twijfel het hoogtepunt, met het Parthenon als beroemdste tempel. Daarnaast kun je het Akropolismuseum bezoeken, waar veel archeologische vondsten te zien zijn. Ook de oude agora en het Olympieion geven een goed beeld van het klassieke Griekenland. In het centrum van de stad vind je daarnaast historische wijken zoals Plaka, waar oude straatjes en gebouwen de sfeer van vroeger behouden hebben. Athene is daardoor een ideale bestemming voor iedereen die zich wil onderdompelen in de geschiedenis van de oude wereld.', 'athens.png'),
(27, 'Istanbul', 'Türkiye', 'Istanbul is de grootste stad van Turkije en ligt op de grens van Europa en Azië, gescheiden door de Bosporus. De stad heeft een unieke ligging en een rijke geschiedenis die teruggaat tot de oudheid. Ooit bekend als Byzantium en later Constantinopel, was Istanbul eeuwenlang het centrum van grote rijken. Bezienswaardigheden zoals de Hagia Sophia, de Blauwe Moskee en het Topkapi-paleis trekken jaarlijks miljoenen bezoekers.', 265, 'Turkey.png', 'Europa', 0, 1, 0, 0, 1, 'Welkom in Istanbul, een stad waar oost en west elkaar ontmoeten. Tijdens een bezoek ontdek je een unieke mix van Europese en Aziatische invloeden, zichtbaar in de architectuur, cultuur en sfeer. De stad bruist van het leven, met drukke bazaars, historische wijken en indrukwekkende monumenten. Overal in Istanbul voel je de geschiedenis van grote rijken die hier hun sporen hebben achtergelaten. Tegelijkertijd is het een moderne metropool met een levendig stadsleven. Voor reizigers die geïnteresseerd zijn in cultuur en geschiedenis is Istanbul een bestemming die blijft fascineren.', 'Istanbul heeft een lange en complexe geschiedenis die meer dan 2.500 jaar teruggaat. De stad werd oorspronkelijk gesticht als Byzantium en groeide later uit tot Constantinopel, de hoofdstad van het Byzantijnse Rijk. In 1453 werd de stad veroverd door de Ottomanen, waarna het een belangrijk centrum werd van het Ottomaanse Rijk. Door de eeuwen heen heeft Istanbul een sleutelrol gespeeld in handel, politiek en religie tussen Europa en Azië. Veel historische gebouwen uit zowel de Byzantijnse als Ottomaanse periode zijn nog steeds zichtbaar, waardoor de stad een uniek historisch erfgoed heeft.', 'Istanbul biedt een enorme hoeveelheid historische en culturele bezienswaardigheden. De Hagia Sophia is een van de bekendste monumenten ter wereld en laat de rijke geschiedenis van de stad goed zien. Daarnaast kun je de Blauwe Moskee, het Topkapi-paleis en de Grand Bazaar bezoeken. Ook een boottocht over de Bosporus is een populaire manier om de stad te ervaren en de twee continenten te zien. In de oude wijken vind je sfeervolle straatjes, markten en lokale restaurants. Dankzij de combinatie van historie en stadsleven is Istanbul een unieke bestemming waar altijd iets te ontdekken valt.', 'istanbul.png');
INSERT INTO `Reizen` (`Reis_id`, `Bestemming`, `Land`, `korte_beschrijving`, `Prijs`, `Vlag`, `Continent`, `Strand_en_zon`, `Stedentrip`, `Wintersport`, `Natuur`, `Cultuur`, `Welkom_bericht`, `Historie`, `Wat_te_doen`, `kaart_afbeelding`) VALUES
(28, 'Bali', 'Indonesië', 'Bali is een Indonesisch eiland dat wereldwijd bekendstaat om zijn tropische stranden, groene rijstvelden en rijke cultuur. Het eiland trekt jaarlijks miljoenen bezoekers die komen voor de combinatie van ontspanning en traditie. Naast de prachtige kustlijn vind je er tempels, lokale ceremonies en een unieke Balinese sfeer. Door het warme klimaat en de veelzijdigheid is Bali een van de populairste vakantiebestemmingen in Azië.', 1150, 'Indonesia.png', 'Azië', 1, 1, 0, 0, 0, 'Welkom op Bali, een eiland waar strand en cultuur hand in hand gaan. Hier kun je genieten van zonovergoten stranden, helderblauw water en een ontspannen sfeer, maar ook kennismaken met eeuwenoude tradities en kleurrijke ceremonies. Overal op het eiland zie je tempels, offers en culturele gebruiken die het dagelijks leven bijzonder maken. Of je nu wilt relaxen aan zee, surfen op de golven of het binnenland wilt verkennen, Bali biedt voor iedere reiziger iets unieks. Het is een bestemming die rust en beleving perfect combineert.', 'Bali heeft een lange geschiedenis die sterk verbonden is met het hindoeïsme en de Indonesische archipel. Het eiland ontwikkelde zich eeuwenlang als cultureel en religieus centrum, met invloeden uit India en andere delen van Zuidoost-Azië. In de zestiende eeuw kwamen er grote veranderingen door de opkomst van het islamitische rijk in Indonesië, waardoor Bali een van de weinige hindoeïstische regio’s in het land bleef. Tijdens de koloniale periode kwam het eiland onder Nederlandse invloed. Tegenwoordig staat Bali wereldwijd bekend om zijn goed bewaarde tradities en unieke culturele identiteit.', 'Bali biedt een brede mix van strandactiviteiten en culturele ervaringen. Langs de kust kun je zwemmen, surfen of ontspannen op bekende stranden zoals Kuta en Seminyak. Daarnaast zijn er talloze tempels te bezoeken, zoals Tanah Lot en Uluwatu, die een belangrijk deel van de Balinese cultuur laten zien. In het binnenland vind je rijstterrassen en kleine dorpen waar traditionele gebruiken nog dagelijks zichtbaar zijn. Ook zijn er markten, dansvoorstellingen en lokale gerechten die je kunt ontdekken. Bali is daarmee een bestemming waar strand en cultuur elkaar versterken en samen een unieke reiservaring vormen.', 'bali.png'),
(29, 'Malé', 'Malidiven', 'Malé is de hoofdstad van de Malediven en ligt op een klein eiland midden in de Indische Oceaan. De stad wordt omringd door helderblauw water, witte zandstranden en kleurrijke koraalriffen. Hoewel Malé zelf een compacte en drukke stad is, draait alles in de omgeving om strand, zee en ontspanning. Het tropische klimaat en de ligging maken het een populaire toegangspoort tot de paradijselijke eilanden van de Malediven.', 1150, 'Maldives.png', 'Azië', 1, 1, 0, 0, 0, 'Welkom in Malé, het kloppende hart van de Malediven en de toegang tot een van de mooiste strandbestemmingen ter wereld. Zodra je aankomt, word je omringd door warm weer, helder water en een ontspannen eilandgevoel. Hoewel de stad zelf compact en levendig is, ligt de echte schoonheid vooral in de omliggende eilanden en stranden. Hier kun je volledig tot rust komen, genieten van de zon en het tropische landschap. Malé is de perfecte start van een vakantie vol strand, zee en pure ontspanning.', 'Malé heeft een lange geschiedenis als politiek en economisch centrum van de Malediven. Het eiland werd al vroeg bewoond en groeide uit tot het bestuurscentrum van het eilandrijk. Door de strategische ligging in de Indische Oceaan speelde Malé een belangrijke rol in handel en zeevaart tussen Azië, Afrika en het Midden-Oosten. In de loop der tijd ontwikkelde de stad zich tot een dichtbevolkte hoofdstad, terwijl de omliggende eilanden steeds belangrijker werden voor visserij en later toerisme. Tegenwoordig is Malé vooral bekend als startpunt voor strandvakanties in de Malediven.', 'In en rond Malé draait alles om strand en zee. Vanuit de stad kun je eenvoudig uitstapjes maken naar omliggende eilanden met witte zandstranden en helder water. Hier kun je zwemmen, snorkelen of duiken tussen kleurrijke koraalriffen en tropische vissen. Ook zijn er luxe resorts en rustige stranden waar je volledig kunt ontspannen. In Malé zelf kun je lokale markten bezoeken en het dagelijks leven van de Malediven ervaren. De echte aantrekkingskracht van deze bestemming ligt echter in de natuur en de stranden, die zorgen voor een ultiem tropisch vakantiegevoel.', 'male.jpg'),
(30, 'Beijing', 'China', 'Beijing is de hoofdstad van China en een van de oudste en meest invloedrijke steden ter wereld. De stad combineert een rijke geschiedenis met een moderne skyline en is het politieke en culturele hart van het land. Bezienswaardigheden zoals de Verboden Stad, de Tempel van de Hemel en de nabijgelegen Chinese Muur trekken jaarlijks miljoenen bezoekers. Beijing is een stad waar eeuwenoude tradities en een snelgroeiende metropool naast elkaar bestaan.', 1000, 'China.png', 'Azië', 0, 1, 0, 0, 1, 'Welkom in Beijing, een stad waar je door duizenden jaren geschiedenis wandelt terwijl je in een moderne wereldstad staat. Overal vind je sporen van het keizerlijke China, van indrukwekkende paleizen tot oude tempelcomplexen. Tegelijkertijd is Beijing een levendige metropool met brede straten, moderne gebouwen en een bruisend stadsleven. De stad biedt een unieke mix van cultuur, traditie en innovatie. Of je nu geïnteresseerd bent in geschiedenis, architectuur of het ontdekken van de Chinese cultuur, Beijing is een bestemming die je veel zal laten zien en ervaren.', 'Beijing heeft een geschiedenis die meer dan 3.000 jaar teruggaat en is lange tijd het centrum geweest van verschillende Chinese dynastieën. Vooral tijdens de Ming- en Qing-dynastieën groeide de stad uit tot het politieke en culturele hart van China. De Verboden Stad diende eeuwenlang als keizerlijk paleis en symbool van de macht. Ook werd de Chinese Muur in de omgeving verder versterkt ter bescherming van het rijk. In de twintigste eeuw werd Beijing de hoofdstad van de Volksrepubliek China. Tegenwoordig is het een stad waar oude tradities en moderne ontwikkeling samenkomen.', 'Beijing biedt een enorme hoeveelheid historische en culturele bezienswaardigheden. De Verboden Stad is een van de belangrijkste paleiscomplexen ter wereld en geeft een goed beeld van het keizerlijke verleden. Daarnaast kun je de Tempel van de Hemel bezoeken of wandelen door traditionele hutongs in de oude stadsdelen. Net buiten de stad ligt de Chinese Muur, een van de meest iconische bouwwerken ter wereld. Ook moderne wijken met winkels, restaurants en musea laten de veelzijdigheid van Beijing zien. Dankzij deze combinatie van geschiedenis en cultuur is Beijing een van de meest indrukwekkende steden van Azië.', 'beijing.png'),
(31, 'Seoul', 'Zuid-Korea', 'Seoul is de hoofdstad van Zuid-Korea en een van de meest dynamische steden van Azië. De stad combineert moderne technologie en wolkenkrabbers met eeuwenoude paleizen en traditionele wijken. Met miljoenen inwoners is Seoul een belangrijk centrum voor cultuur, economie en entertainment. Bezoekers kunnen er genieten van een bruisend stadsleven, uitgebreide winkelgebieden en een sterke popcultuur die wereldwijd invloed heeft. Seoul is een stad waar oud en nieuw voortdurend samenkomen.', 1075, 'Zuid-korea.png', 'Azië', 0, 1, 0, 0, 0, 'Welkom in Seoul, een stad vol energie, contrasten en eindeloze mogelijkheden. Hier vind je ultramoderne wijken met neonverlichting naast rustige tempels en historische paleizen. Overdag kun je door drukke winkelstraten lopen, lokale gerechten proberen of moderne architectuur bewonderen. ’s Avonds komt de stad echt tot leven met entertainment, markten en een levendige sfeer. Seoul is een bestemming die constant in beweging is en je telkens weer iets nieuws laat ontdekken. Of je nu komt voor cultuur, eten of het stadsleven, Seoul biedt een unieke ervaring.', 'Seoul heeft een geschiedenis die meer dan 2.000 jaar teruggaat en is sinds de Joseon-dynastie de hoofdstad van Korea. In deze periode werden belangrijke paleizen gebouwd, zoals Gyeongbokgung, die nog steeds te bezoeken zijn. Tijdens de Koreaanse Oorlog werd de stad zwaar beschadigd, maar daarna opnieuw opgebouwd en gemoderniseerd in hoog tempo. In de tweede helft van de twintigste eeuw groeide Seoul uit tot een van de belangrijkste economische en technologische centra van de wereld. Vandaag de dag is het een stad waar geschiedenis en hypermoderne ontwikkeling naast elkaar bestaan.', 'Seoul biedt een enorme variatie aan activiteiten. Je kunt historische paleizen bezoeken zoals Gyeongbokgung of Changdeokgung en traditionele wijken zoals Bukchon Hanok Village verkennen. Daarnaast zijn er moderne winkelgebieden zoals Myeongdong en Gangnam, waar je mode, eten en entertainment vindt. Ook de N Seoul Tower biedt een prachtig uitzicht over de stad. Voor liefhebbers van cultuur en stadsleven is Seoul ideaal, omdat elke wijk een andere sfeer heeft. Dankzij de combinatie van traditie en moderniteit is er in Seoul altijd iets nieuws te ontdekken.', 'seoul.png'),
(32, 'Dubai', 'VAE', 'Dubai is een moderne stad in de Verenigde Arabische Emiraten en staat bekend om haar futuristische skyline, luxe en snelle ontwikkeling. De stad ligt aan de Perzische Golf en is in korte tijd uitgegroeid tot een wereldwijde metropool. Iconische gebouwen zoals de Burj Khalifa en enorme winkelcentra trekken jaarlijks miljoenen bezoekers. Dubai combineert woestijnlandschap met ultramoderne architectuur en is een populaire bestemming voor stedentrips en luxe reizen.', 625, 'VAE.png', 'Azië', 0, 1, 0, 0, 0, 'Welkom in Dubai, een stad waar alles groter, hoger en moderner lijkt te zijn. Hier vind je indrukwekkende wolkenkrabbers, luxe winkelcentra en een skyline die wereldwijd bekend is. Tegelijkertijd biedt Dubai ook een kijkje in de Arabische cultuur en tradities, die je terugziet in markten, architectuur en lokale gebruiken. Of je nu door de stad wilt wandelen, wilt winkelen in enorme malls of simpelweg de unieke sfeer wilt ervaren, Dubai heeft voor iedere bezoeker iets te bieden. Het is een bestemming die modern stadsleven combineert met een bijzondere culturele achtergrond.', 'Dubai was oorspronkelijk een kleine vissers- en handelsnederzetting aan de kust van de Perzische Golf. De economie draaide lange tijd vooral om visserij, parelduiken en handel. Vanaf het midden van de twintigste eeuw veranderde de stad snel door de ontdekking van olie, wat leidde tot enorme economische groei. Onder leiding van de heersende families ontwikkelde Dubai zich in korte tijd tot een moderne wereldstad met ambitieuze bouwprojecten en internationale handel. Tegenwoordig is het een van de meest vooruitstrevende steden ter wereld en een belangrijk centrum voor toerisme en business.', 'Dubai biedt een breed scala aan moderne en luxe activiteiten. Je kunt de Burj Khalifa bezoeken, het hoogste gebouw ter wereld, of winkelen in gigantische winkelcentra zoals de Dubai Mall. Daarnaast zijn er kunstmatige eilanden zoals Palm Jumeirah en indrukwekkende hotels en resorts. In de oude wijk Dubai Creek kun je juist de traditionele kant van de stad ontdekken met markten en historische gebouwen. Ook woestijnsafari’s net buiten de stad zijn populair. Dankzij de combinatie van moderniteit en traditie is Dubai een veelzijdige bestemming waar altijd iets te beleven valt.', 'dubai.png'),
(33, 'Bangkok', 'Thailand', 'Bangkok is de hoofdstad van Thailand en een van de meest bezochte steden van Azië. De stad staat bekend om haar levendige straatleven, indrukwekkende tempels en rijke cultuur. Met miljoenen inwoners is Bangkok een bruisende metropool waar moderne wolkenkrabbers en traditionele markten naast elkaar bestaan. Bezoekers komen vooral voor de unieke mix van cultuur, eten en stadsleven, waardoor Bangkok een populaire bestemming is voor reizigers van over de hele wereld.', 950, 'Thailand.png', 'Azië', 0, 1, 0, 0, 1, 'Welkom in Bangkok, een stad die nooit stil lijkt te staan. Overal waar je kijkt zie je contrasten: glimmende tempels naast drukke markten, moderne winkelcentra naast traditionele straatverkopers. De stad heeft een unieke energie die je meteen voelt zodra je aankomt. Bangkok is een plek waar cultuur en dagelijks leven volledig door elkaar lopen. Je kunt er genieten van heerlijke Thaise gerechten, indrukwekkende tempels bezoeken en het drukke stadsleven ervaren. Of je nu voor het eerst komt of al vaker bent geweest, Bangkok blijft verrassen met zijn levendige sfeer en rijke cultuur.', 'Bangkok werd in 1782 gesticht als hoofdstad van het Koninkrijk Siam, het huidige Thailand. De stad groeide snel uit tot het politieke en culturele centrum van het land. Tijdens de Rattanakosin-periode werden belangrijke tempels en paleizen gebouwd, waaronder het Grand Palace. In de twintigste eeuw ontwikkelde Bangkok zich tot een moderne metropool met snelle economische groei en urbanisatie. Ondanks deze modernisering zijn veel traditionele elementen van de Thaise cultuur behouden gebleven. Tegenwoordig is Bangkok een stad waar eeuwenoude tradities en moderne ontwikkelingen samenkomen.', 'Bangkok biedt een enorme variatie aan activiteiten. Je kunt het Grand Palace bezoeken en de beroemde Wat Phra Kaew-tempel bewonderen, of andere indrukwekkende tempels zoals Wat Arun en Wat Pho verkennen. Daarnaast zijn er levendige markten zoals Chatuchak Market en drijvende markten waar je de lokale cultuur kunt ervaren. Ook het moderne stadsleven is goed zichtbaar in winkelcentra, restaurants en skybars met uitzicht over de stad. Dankzij deze mix van cultuur, eten en entertainment is Bangkok een bestemming waar altijd iets te ontdekken valt.', 'bangkok.jpg'),
(35, 'Sydney', 'Australië', 'Sydney is de grootste stad van Australië en ligt aan de zuidoostkust van het land. De stad staat bekend om haar iconische skyline, natuurlijke haven en wereldberoemde bezienswaardigheden zoals het Sydney Opera House en de Harbour Bridge. Met een mix van stranden, moderne architectuur en een ontspannen levensstijl is Sydney een van de populairste stedelijke bestemmingen ter wereld. De stad trekt jaarlijks miljoenen bezoekers die komen voor cultuur, natuur en het bruisende stadsleven.', 1375, 'Australia.png', 'Oceanië', 0, 1, 0, 0, 0, 'Welkom in Sydney, een stad waar modern stadsleven en natuur naadloos in elkaar overlopen. Hier vind je een indrukwekkende skyline, een prachtige haven en een levendige sfeer die typisch is voor Australië. Overdag kun je de stad verkennen, iconische gebouwen bezoeken of genieten van de stranden in en rond de stad. Sydney heeft een ontspannen maar energieke sfeer die het uniek maakt als wereldstad. Of je nu komt voor cultuur, architectuur of gewoon om de stad te ervaren, Sydney biedt voor iedere reiziger een onvergetelijke ervaring.', 'Sydney werd in 1788 gesticht als eerste Europese nederzetting in Australië. De stad groeide uit tot het belangrijkste economische en culturele centrum van het land. Door de ligging aan een natuurlijke haven ontwikkelde Sydney zich snel als handelsstad. In de twintigste eeuw werd de stad wereldwijd bekend, onder andere door de bouw van het Sydney Opera House, dat tegenwoordig een icoon is van Australië. Tegenwoordig is Sydney een moderne, multiculturele stad met een sterke internationale uitstraling.', 'Sydney biedt een grote variatie aan activiteiten. Je kunt het Sydney Opera House bezoeken, wandelen over de Harbour Bridge of genieten van het uitzicht op de haven. Daarnaast zijn er verschillende wijken met elk hun eigen sfeer, zoals het historische The Rocks en het moderne CBD. Ook stranden zoals Bondi Beach en Manly Beach liggen dicht bij de stad en zijn populair voor ontspanning en surfen. Dankzij de combinatie van stad, cultuur en kust is Sydney een veelzijdige bestemming waar altijd iets te beleven valt.', 'sydney.jpg');

